"use client"

import * as React from "react"
import { MenuIcon } from "lucide-react"
import { cn } from "cn"
import { Link } from "react-aria-components"

import { LinkButton } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Icon } from "@/components/ui/icon"
import { Logo } from "@/components/ui/logo"

type NavItem = { label: string; href: string }
type Action = { label: string; href: string; variant?: "default" | "ghost" | "outline" }

/**
 * tailark mist hero-section-1 header rebuilt on React Aria: brand is the Logo
 * in a React Aria Link, nav entries are aria-nova LinkButtons inside a named
 * <nav>, and the small-screen menu is a Disclosure (no Button asChild, no
 * manual open state). Members: surface (solid | transparent | glass), tone
 * (base | inverse), nav-placement (leading | centered), position (sticky | static).
 */
export default function SiteHeader({
  brand = { name: "Clossys", href: "/" },
  nav = [
    { label: "Features", href: "#features" },
    { label: "Pricing", href: "#pricing" },
    { label: "About", href: "#about" },
  ],
  actions = [
    { label: "Sign in", href: "#", variant: "ghost" },
    { label: "Get started", href: "#" },
  ],
  navLabel = "Primary",
  surface = "solid",
  tone = "base",
  navPlacement = "centered",
  position = "sticky",
}: {
  brand?: { name: string; href: string; mark?: React.ReactNode }
  nav?: NavItem[]
  actions?: Action[]
  navLabel?: string
  surface?: "solid" | "transparent" | "glass"
  tone?: "base" | "inverse"
  navPlacement?: "leading" | "centered"
  position?: "sticky" | "static"
}) {
  const [open, setOpen] = React.useState(false)
  return (
    <header
      data-slot="site-header"
      data-surface={surface}
      data-tone={tone}
      className={cn(
        "z-20 w-full",
        position === "sticky" && "sticky top-0",
        surface === "solid" && "border-b border-border bg-background",
        surface === "glass" && "border-b border-border/60 bg-background/75 backdrop-blur-lg",
        surface === "transparent" && "bg-transparent",
        tone === "inverse" && "dark"
      )}
    >
      <Collapsible isExpanded={open} onExpandedChange={setOpen}>
        <div className="mx-auto flex max-w-5xl items-center gap-6 px-6 py-3">
          <Link href={brand.href} aria-label={brand.name} className="flex shrink-0 items-center rounded-md outline-none focus-visible:ring-3 focus-visible:ring-ring/50">
            <Logo content="lockup" size="sm" name={brand.name} mark={brand.mark} />
          </Link>
          {nav.length > 0 && (
            <nav aria-label={navLabel} className={cn("hidden lg:block", navPlacement === "centered" && "mx-auto")}>
              <ul className="flex gap-1">
                {nav.map((n) => (
                  <li key={n.href}>
                    <LinkButton href={n.href} variant="ghost" size="sm" className="text-muted-foreground hover:text-accent-foreground">
                      {n.label}
                    </LinkButton>
                  </li>
                ))}
              </ul>
            </nav>
          )}
          <div className={cn("hidden items-center gap-2 lg:flex", navPlacement === "leading" && "ml-auto")}>
            {actions.map((a) => (
              <LinkButton key={a.label} href={a.href} variant={a.variant ?? "default"} size="sm">
                {a.label}
              </LinkButton>
            ))}
          </div>
          <CollapsibleTrigger className="ml-auto lg:hidden" aria-label={open ? "Close menu" : "Open menu"}>
            <span className="flex size-8 items-center justify-center rounded-lg hover:bg-muted">{open ? <Icon name="close" size="lg" /> : <MenuIcon className="size-5" />}</span>
          </CollapsibleTrigger>
        </div>
        <CollapsibleContent className="lg:hidden">
          <div className="mx-auto flex max-w-5xl flex-col gap-4 border-t border-border px-6 py-4">
            {nav.length > 0 && (
              <nav aria-label={`${navLabel} (menu)`}>
                <ul className="flex flex-col gap-1">
                  {nav.map((n) => (
                    <li key={n.href}>
                      <LinkButton href={n.href} variant="ghost" className="w-full justify-start" onPress={() => setOpen(false)}>
                        {n.label}
                      </LinkButton>
                    </li>
                  ))}
                </ul>
              </nav>
            )}
            <div className="flex flex-col gap-2 sm:flex-row">
              {actions.map((a) => (
                <LinkButton key={a.label} href={a.href} variant={a.variant === "ghost" ? "outline" : (a.variant ?? "default")}>
                  {a.label}
                </LinkButton>
              ))}
            </div>
          </div>
        </CollapsibleContent>
      </Collapsible>
    </header>
  )
}
